class Solution:
    def calculate(self, s: str) -> int:
        self.i = 0
        def parse():
            stack = []
            num = 0
            op = '+'
            while self.i < len(s):
                c = s[self.i]
                if c.isdigit():
                    num = num * 10 + int(c)
                if c == '(':
                    self.i += 1
                    num = parse()
                if c in '+-*/)' or self.i == len(s) - 1:
                    if op == '+':
                        stack.append(num)
                    elif op == '-':
                        stack.append(-num)
                    elif op == '*':
                        stack.append(stack.pop() * num)
                    elif op == '/':
                        stack.append(int(stack.pop() / num))
                    op = c
                    num = 0
                    if c == ')':
                        break
                self.i += 1
            return sum(stack)
        return parse()

